import { X } from 'lucide-react'
import { useEffect } from 'react'

import { cx } from '~/lib/cx'
import { Portal } from '~/components/primitives/portal'
import styles from './lightbox.module.scss'

export interface LightboxProps {
  open: boolean
  src: string
  alt?: string
  onClose: () => void
  caption?: string
  className?: string
}

/** Full-screen image viewer. */
export function Lightbox({ open, src, alt = '', onClose, caption, className }: LightboxProps) {
  useEffect(() => {
    if (!open) return
    const onKeyDown = (event: KeyboardEvent) => {
      if (event.key === 'Escape') onClose()
    }
    document.addEventListener('keydown', onKeyDown)
    return () => document.removeEventListener('keydown', onKeyDown)
  }, [open, onClose])

  if (!open) return null

  return (
    <Portal>
      <div
        className={cx(styles.root, className)}
        role="dialog"
        aria-modal="true"
        aria-label={alt || 'Image preview'}
        onClick={onClose}
      >
        <button type="button" className={styles.close} onClick={onClose} aria-label="Close">
          <X aria-hidden />
        </button>
        <figure className={styles.figure} onClick={(event) => event.stopPropagation()}>
          <img className={styles.image} src={src} alt={alt} />
          {caption ? <figcaption className={styles.caption}>{caption}</figcaption> : null}
        </figure>
      </div>
    </Portal>
  )
}

@use '../../styles' as vz;

.root {
  position: fixed;
  inset: 0;
  z-index: vz.z('modal');
  display: grid;
  place-items: center;
  padding: vz.space(6);
  background: rgb(0 0 0 / 0.82);
}

.close {
  position: absolute;
  top: vz.space(4);
  right: vz.space(4);
  display: grid;
  place-items: center;
  width: vz.space(10);
  height: vz.space(10);
  border-radius: 50%;
  color: white;
  background: rgb(255 255 255 / 0.12);

  svg {
    width: 20px;
    height: 20px;
  }
}

.figure {
  max-width: min(92vw, 80rem);
  max-height: 88vh;
  margin: 0;
}

.image {
  max-width: 100%;
  max-height: 82vh;
  border-radius: vz.radius('lg');
  object-fit: contain;
}

.caption {
  margin-top: vz.space(3);
  color: rgb(255 255 255 / 0.78);
  font-size: vz.font-size('sm');
  text-align: center;
}
